import{_ as d,C as t,o as r,c as s,a1 as a,E as n}from"./chunks/framework.DceXOx8u.js";const b=JSON.parse('{"title":"Modelo de amenazas","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/modelo-amenazas"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/modelo-amenazas"}]]},"headers":[],"relativePath":"es/guide/modelo-amenazas.md","filePath":"es/guide/modelo-amenazas.md"}'),i={name:"es/guide/modelo-amenazas.md"};function l(c,e,p,u,m,h){const o=t("Mermaid");return r(),s("div",null,[e[0]||(e[0]=a('<h1 id="modelo-de-amenazas" tabindex="-1">Modelo de amenazas <a class="header-anchor" href="#modelo-de-amenazas" aria-label="Permalink to &quot;Modelo de amenazas&quot;">​</a></h1><p>Qué protege este framework, de quién, y qué <strong>no</strong> protege. El safety gate de <a href="https://github.com/andresayac/botmesh/blob/main/ROADMAP.md" target="_blank" rel="noreferrer"><code>ROADMAP.md</code></a> exige que este documento y su <a href="https://github.com/andresayac/botmesh/blob/main/CONTRIBUTING.md#release-checklist" target="_blank" rel="noreferrer">checklist de release</a> estén al día; los hallazgos por superficie, los arreglos y los riesgos residuales viven en <a href="./seguridad">Seguridad</a>.</p><h2 id="activos" tabindex="-1">Activos <a class="header-anchor" href="#activos" aria-label="Permalink to &quot;Activos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activo</th><th>Por qué importa</th><th>Dónde vive</th></tr></thead><tbody><tr><td>Credenciales de sesión</td><td>Una sesión de WhatsApp/Telegram/IMAP <strong>es</strong> la cuenta: filtrarla entrega la identidad</td><td><code>sessions/</code>, <code>*_sessions/</code>, config del provider, <code>baileys_store.json</code></td></tr><tr><td>Secretos del bot</td><td>Tokens de proveedor, API keys, secretos de webhook, app secrets</td><td>Entorno/<code>.env</code>, config del provider, <code>BotConfig</code></td></tr><tr><td>Contenido y media de los mensajes</td><td>Datos personales de los usuarios finales (cuerpos, captions, adjuntos, ubicaciones)</td><td>Store, checkpoints, journal, logs, trazas</td></tr><tr><td>Datos operativos</td><td>Configs multi-tenant, destinatarios de campañas, notas de inbox, gate runs</td><td><code>manager</code>, <code>deployments</code>, <code>inbox</code>, <code>crm</code>, <code>campaigns</code>, <code>hub</code></td></tr><tr><td>Fronteras entre tenants</td><td>Un cliente nunca debe leer ni manejar el bot de otro</td><td>Namespaces, claves del store, REST <code>/v1</code>, <code>tenant-kv</code></td></tr><tr><td>Disponibilidad del bot</td><td>Un bot colgado o inundado es una caída de negocio y, en WhatsApp, riesgo de baneo</td><td>Ingress, colas del dispatcher, rate limiter</td></tr></tbody></table><h2 id="fronteras-de-confianza" tabindex="-1">Fronteras de confianza <a class="header-anchor" href="#fronteras-de-confianza" aria-label="Permalink to &quot;Fronteras de confianza&quot;">​</a></h2>',5)),n(o,{code:"flowchart%20LR%0A%20%20subgraph%20untrusted%5BNo%20confiable%5D%0A%20%20%20%20P%5BWebhooks%20%2F%20sockets%20de%20la%20plataforma%5D%0A%20%20%20%20U%5BUsuarios%20finales%5D%0A%20%20%20%20L%5BProveedores%20LLM%20y%20herramientas%5D%0A%20%20%20%20A%5BClientes%20MCP%20%2F%20agentes%20de%20c%C3%B3digo%5D%0A%20%20end%0A%20%20subgraph%20edge%5BBorde%20-%20este%20framework%5D%0A%20%20%20%20S%5B%22%40botmesh%2Fserver%3Cbr%2F%3Ebody%20crudo%2C%20l%C3%ADmites%2C%20timeouts%22%5D%0A%20%20%20%20V%5BVerificaci%C3%B3n%20de%20firma%20del%20provider%5D%0A%20%20%20%20D%5BDispatcher%20%2B%20listas%20de%20acceso%5D%0A%20%20%20%20C%5BRuntime%20del%20core%5D%0A%20%20end%0A%20%20subgraph%20trusted%5BControlado%20por%20el%20operador%5D%0A%20%20%20%20ST%5B(Store%20%2F%20durabilidad)%5D%0A%20%20%20%20OP%5BC%C3%B3digo%20del%20bot%2C%20plugins%2C%20flows%5D%0A%20%20end%0A%20%20P%20--%3E%20S%20--%3E%20V%20--%3E%20D%20--%3E%20C%0A%20%20U%20--%3E%20P%0A%20%20L%20--%3E%20C%0A%20%20A%20--%3E%7Cstdio%7C%20OP%0A%20%20C%20--%3E%20ST%0A%20%20OP%20--%3E%20ST%0A"}),e[1]||(e[1]=a('<p>Confiable: el código del bot, los plugins y los flows del operador, y la máquina donde corre el proceso. No confiable: cada payload de plataforma, cada mensaje de usuario, cada respuesta del modelo, cada byte descargado de una URL que venga de un payload y cualquier cliente MCP que hable con <code>@botmesh/mcp</code>.</p><h2 id="amenazas-y-controles" tabindex="-1">Amenazas y controles <a class="header-anchor" href="#amenazas-y-controles" aria-label="Permalink to &quot;Amenazas y controles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Amenaza</th><th>Superficie</th><th>Control</th><th>Riesgo residual</th></tr></thead><tbody><tr><td>T1</td><td>Webhook falsificado (mensaje o llamada falsos)</td><td>13 canales</td><td>Firma de la plataforma sobre el body <strong>crudo</strong>, comparación en tiempo constante, el provider no arranca sin credenciales</td><td>Replay donde la plataforma no firma timestamp (ver abajo)</td></tr><tr><td>T2</td><td>Inundación / body gigante</td><td>Ingress de webhooks</td><td><code>@botmesh/server</code> acota tamaño, pone timeout por body y por ingest, limita concurrencia, <code>413</code>/<code>408</code>/<code>503</code></td><td>El operador sigue dimensionando el proceso y el proxy</td></tr><tr><td>T3</td><td>SSRF desde una URL del usuario (media, TTS, embeddings)</td><td>Toda descarga saliente</td><td><code>secureFetch</code>: HTTPS, rangos privados rechazados, socket fijado a la IP verificada, redirects revalidados, topes de tamaño y tiempo</td><td>La respuesta DNS puede cambiar después solo si un provider se salta <code>secureFetch</code></td></tr><tr><td>T4</td><td>Path traversal vía ids (tenant, bot, chat, flow)</td><td>REST <code>/v1</code>, manager, docs del MCP</td><td>Ids de bot y de tenant restringidos a <code>[A-Za-z0-9][A-Za-z0-9_.-]{0,63}</code> (los de flujo admiten además <code>:</code>), nombres de archivo derivados, rutas de docs resueltas y rechazadas fuera de la raíz</td><td>Ninguno conocido</td></tr><tr><td>T5</td><td>Ejecución de código desde un flujo almacenado</td><td>Documentos JSON de flujo</td><td>Esquema de datos: sin código, sin imports, sin <code>eval</code>; gramática de expresiones segura (sin regex, sin acceso al prototipo, con topes de longitud/profundidad); el paso <code>http</code> pasa por <code>secureFetch</code></td><td>Un paso <code>http</code> puede llamar a un endpoint público que el operador permitió</td></tr><tr><td>T6</td><td>Lectura/escritura entre tenants</td><td>Store, manager, paquetes de producto</td><td>Namespace por bot, claves por tenant en <code>tenant-kv</code>, compare-and-set, scopes del REST y <code>404</code> para otros tenants</td><td>Un <code>IStore</code> propio puede romper su propia aislamiento</td></tr><tr><td>T7</td><td>Secretos o datos personales en logs/trazas</td><td>Logger, OpenTelemetry</td><td>El framework no registra cuerpos, prompts, payloads de QR ni tokens; los spans llevan ids según la política <code>ids</code> (<code>hash</code> por defecto) y nunca contenido</td><td>Código del operador que registre <code>ctx.body</code></td></tr><tr><td>T8</td><td>Inyección de prompt que maneja herramientas</td><td><code>@botmesh/ai</code></td><td>Las herramientas se eligen por llamada, las destructivas exigen <code>confirm: true</code>, el modelo no puede inventar ids (<code>tools: [&#39;id&#39;]</code> filtra el conjunto configurado)</td><td>Una herramienta de solo lectura puede filtrar lo que el operador le dio</td></tr><tr><td>T9</td><td>Código no confiable dentro del proceso</td><td>Plugins</td><td><code>Plugin.install</code> es síncrono, el plugin solo recibe la fachada con scope, sin sandbox</td><td><strong>Los plugins corren en el proceso con permisos de Node: instala solo código que confíes</strong></td></tr><tr><td>T10</td><td>Baneo del número de WhatsApp</td><td>Baileys / gateways</td><td>Rate limiter opt-in, typing/pacing, sin spam de botones, <code>exclusiveSession</code> en transportes de conexión única</td><td>Automatizar WhatsApp Web es no oficial y siempre conlleva riesgo de baneo</td></tr><tr><td>T11</td><td>Un agente lee o escribe lo que no debe</td><td><code>@botmesh/mcp</code></td><td>Solo stdio local (sin listener de red), herramientas de solo lectura, sin <code>eval</code>, lectura de docs confinada a la raíz configurada, sin escrituras a disco</td><td>El cliente decide qué hace con las respuestas</td></tr><tr><td>T12</td><td>Replay de un webhook capturado</td><td>Meta, Telegram, Twilio, HighLevel, Gupshup, WPPConnect</td><td>Dedupe en memoria por chat e id de mensaje (<code>BotConfig.dedupe</code>, por proceso); con <a href="./durabilidad">durabilidad</a>, el journal de entrada también descarta reentregas entre reinicios y réplicas</td><td>No hay timestamp de plataforma para imponer una ventana; mantén los endpoints en HTTPS</td></tr></tbody></table><h2 id="supuestos" tabindex="-1">Supuestos <a class="header-anchor" href="#supuestos" aria-label="Permalink to &quot;Supuestos&quot;">​</a></h2><ul><li>HTTPS termina en el proxy inverso del operador o en la plataforma; el proceso habla HTTP plano en la interfaz de loopback.</li><li>La máquina no se comparte con usuarios no confiables: el código del bot y los plugins son de confianza.</li><li>Los secretos llegan por el entorno; el framework nunca lee <code>.env</code> por su cuenta.</li><li>El store del operador está autenticado y no es alcanzable desde internet.</li></ul><h2 id="fuera-de-alcance" tabindex="-1">Fuera de alcance <a class="header-anchor" href="#fuera-de-alcance" aria-label="Permalink to &quot;Fuera de alcance&quot;">​</a></h2><ul><li>Autenticación multi-tenant más allá de los tokens del manager (sin OIDC ni RBAC).</li><li>Endurecimiento del host, contenedor, base de datos o proxy del operador.</li><li>Cumplimiento de los términos de WhatsApp / Meta / Telegram / Twilio y la base legal para tratar datos de los usuarios finales.</li><li>Denegación de servicio por encima de los límites del ingress (capa de red).</li><li>Calidad del modelo, alucinaciones o políticas de retención de cada proveedor.</li></ul><h2 id="reportar" tabindex="-1">Reportar <a class="header-anchor" href="#reportar" aria-label="Permalink to &quot;Reportar&quot;">​</a></h2><p>Abre un advisory privado siguiendo <a href="https://github.com/andresayac/botmesh/blob/main/SECURITY.md" target="_blank" rel="noreferrer"><code>SECURITY.md</code></a>; nunca un issue público. Todo arreglo entra con un test de regresión llamado <code>security-audit</code> en su paquete.</p>',9))])}const f=d(i,[["render",l]]);export{b as __pageData,f as default};
